import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import api from '../api/axios';
import { useAuth } from '../context/AuthContext';
import { Card, Button, Input, Alert } from '../components/UI';

export default function Register() {
  const [form, setForm] = useState({ email: '', national_id: '', full_name: '', phone_number: '', password: '', password_confirm: '' });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handle = async (e) => {
    e.preventDefault();
    setLoading(true); setErrors({});
    try {
      const res = await api.post('/auth/register/', form);
      const { tokens, user } = res.data.data;
      login(tokens, user);
      navigate('/dashboard');
    } catch (err) {
      const details = err.response?.data?.error?.details || {};
      setErrors(details);
    } finally {
      setLoading(false);
    }
  };

  const F = ({ k, ...props }) => (
    <Input error={errors[k]?.[0] || errors[k]} value={form[k]} onChange={e => set(k, e.target.value)} {...props} />
  );

  return (
    <div style={{ maxWidth: 480, margin: '32px auto' }} className="fade-in">
      <div style={{ textAlign: 'center', marginBottom: 28 }}>
        <h1 style={{ fontSize: 24, fontWeight: 700, color: 'var(--text-primary)' }}>Create account</h1>
        <p style={{ fontSize: 13, color: 'var(--text-secondary)', marginTop: 6 }}>Register to verify land ownership</p>
      </div>
      <Card>
        {errors.non_field_errors && <Alert type="danger" style={{ marginBottom: 16 }}>{errors.non_field_errors}</Alert>}
        <form onSubmit={handle} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <F k="full_name" label="Full name" placeholder="Kwame Asante" required />
          <F k="email" label="Email address" type="email" placeholder="you@example.com" required />
          <F k="national_id" label="National ID / Ghana Card" placeholder="GHA-XXXXXX-X" required />
          <F k="phone_number" label="Phone number (optional)" placeholder="+233 XX XXX XXXX" />
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <F k="password" label="Password" type="password" placeholder="Min. 8 chars" required />
            <F k="password_confirm" label="Confirm password" type="password" placeholder="Repeat password" required />
          </div>
          <Button type="submit" loading={loading} style={{ width: '100%', justifyContent: 'center', marginTop: 4 }}>
            Create account
          </Button>
        </form>
      </Card>
      <p style={{ textAlign: 'center', fontSize: 13, color: 'var(--text-secondary)', marginTop: 20 }}>
        Already have an account? <Link to="/login" style={{ color: 'var(--gold)' }}>Sign in</Link>
      </p>
    </div>
  );
}
